/* ==UserStyle==
@name DeepSeek Catppuccin
@namespace github.com/catppuccin/userstyles/styles/deepseek
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/deepseek
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/deepseek/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Adeepseek
@description Soothing pastel theme for DeepSeek
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document url-prefix("https://chat.deepseek.com") {
  @import url("https://prismjs.catppuccin.com/variables.important.css");

  body[data-ds-dark-theme] {
    #catppuccin(@darkFlavor);
  }
  body:not([data-ds-dark-theme]) {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();
    #lib.css-variables();

    #ds-rgb() {
      --ds-bordered-secondary-button-color: var(--dsr-text-1);
      --ds-button-hover-color: initial;
      --ds-input-prefix-color: var(--dsr-text-1);
      --ds-modal-content-color: @surface0;
      --ds-rgb-bg-base: var(--ds-rgb-black);
      --ds-rgb-elevated: #lib.rgbify(@surface0)[];
      --ds-rgb-error: #lib.rgbify(@red)[];
      --ds-rgb-header: 40 40 40;
      --ds-rgb-info: #lib.rgbify(@blue)[];
      --ds-rgb-input-focus: var(--ds-rgb-neutral-900);
      --ds-rgb-input-strong: var(--ds-rgb-neutral-700);
      --ds-rgb-input: var(--ds-rgb-neutral-800);
      --ds-rgb-label-1: #lib.rgbify(@text)[];
      --ds-rgb-label-2: #lib.rgbify(@subtext0)[];
      --ds-rgb-label-3: #lib.rgbify(@overlay1)[];
      --ds-rgb-link: var(--ds-rgb-primary);
      --ds-rgb-primary-foreground: #lib.rgbify(@base)[];
      --ds-rgb-primary: #lib.rgbify(@accent)[];
      --ds-rgb-segmented-button: var(--ds-rgb-neutral-500);
      --ds-rgb-segmented-separator: var(--ds-rgb-neutral-500);
      --ds-rgb-segmented: var(--ds-rgb-neutral-600);
      --ds-rgb-separator-strong: #lib.rgbify(@overlay0)[];
      --ds-rgb-separator: #lib.rgbify(@surface2)[];
      --ds-rgb-success: #lib.rgbify(@green)[];
      --ds-rgb-tag: var(--ds-rgb-neutral-600);
      --ds-rgb-thumb: var(--ds-rgb-neutral-200);
      --ds-rgb-track: var(--ds-rgb-neutral-500);
      --ds-rgb-warning: #lib.rgbify(@yellow)[];
      --ds-rgba-transparent: 255 255 255/0;
      --ds-tabs-active-color: @accent;
      --ds-text-primary-button-color: @accent;
      --ds-rgb-hover: #lib.rgbify(mix(@text, @base, 8%))[];

      --ds-toast-custom-color: @surface0;
      --ds-toast-custom-text-color: @text;
      --ds-toast-cutsom-border: 1px solid @surface1;
      --ds-md-inline-code-color: @base;
    }

    --dsw-alias-bg-base: @base;
    --dsw-alias-bg-layer-1: @mantle;
    --dsw-alias-bg-layer-2: @base;
    --dsw-alias-bg-layer-3: @surface0;

    --dsw-alias-bg-mask-1: rgba(0, 0, 0, 0.5);
    --dsw-alias-bg-mask-2: rgba(0, 0, 0, 0.2);
    --dsw-alias-bg-multi-select: mix(@accent, @mantle, 8%);
    --dsw-alias-bg-skeleton: fade(@text, 8%);

    --dsw-alias-border-inverted2: rgba(255, 255, 255, 0.08);
    --dsw-alias-border-inverted: rgba(255, 255, 255, 0.06);
    --dsw-alias-border-l1: rgba(255, 255, 255, 0.06);
    --dsw-alias-border-l2-darkmode-thin: rgba(255, 255, 255, 0.06);
    --dsw-alias-border-l2: @surface1;
    --dsw-alias-border-l3: @surface2;
    --dsw-alias-border-l4: @overlay0;

    --dsw-alias-brand-primary-invert: @text;
    --dsw-alias-brand-primary: @accent;
    --dsw-alias-brand-text: @accent;

    --dsw-alias-button-contrast-fill: @text;
    --dsw-alias-button-elevated-fill: @surface1;

    --dsw-alias-button-floating-fill: @base;
    --dsw-alias-button-floating-hover: mix(@text, @base, 8%);

    --dsw-alias-button-ghost-active-border: @accent;
    --dsw-alias-button-ghost-active-fill: fade(@accent, 14%);
    --dsw-alias-button-ghost-active-hover: fade(@accent, 18%);

    --dsw-alias-button-primary-dimmed: darken(@accent, 8%);
    --dsw-alias-button-primary-fill: var(--dsw-alias-brand-primary);
    --dsw-alias-button-primary-hover: lighten(@accent, 8%);

    --dsw-alias-interactive-bg-active: fade(@text, 14%);
    --dsw-alias-interactive-bg-hover-accent: fade(@text, 24%);
    --dsw-alias-interactive-bg-hover-danger: fade(@red, 15%);
    --dsw-alias-interactive-bg-hover: fade(@text, 8%);

    --dsw-alias-label-caption: @overlay0;
    --dsw-alias-label-dimmed: @surface1;
    --dsw-alias-label-primary-dimmed: var(--dsw-static-neutral-bluish-100);
    --dsw-alias-label-primary-inverted: var(--dsw-static-neutral-bluish-800);

    --dsw-alias-label-primary: @text;
    --dsw-alias-label-secondary: @subtext0;
    --dsw-alias-label-tertiary: @overlay1;

    --dsw-alias-markdown-citation: var(--dsw-static-neutral-bluish-800);
    --dsw-alias-markdown-code-block-banner: @surface0;
    --dsw-alias-markdown-code-block: @mantle;
    --dsw-alias-markdown-code-segment-selected: var(
      --dsw-static-neutral-bluish-800
    );
    --dsw-alias-markdown-code-segment-unselected: var(
      --dsw-static-neutral-bluish-900
    );
    --dsw-alias-markdown-inline-code: @surface0;
    --dsw-alias-markdown-tag: var(--dsw-static-neutral-bluish-850);

    --dsw-alias-scrollbar-bg-l1: @surface2;
    --dsw-alias-scrollbar-bg-l2: @overlay0;
    --dsw-alias-scrollbar-hover-l1: @overlay0;
    --dsw-alias-scrollbar-hover-l2: @overlay1;

    --dsw-alias-state-error-primary: @red;
    --dsw-alias-state-error-secondary: @red;

    --dsw-alias-state-success-primary: @green;
    --dsw-alias-state-success-secondary: @green;

    --dsw-alias-state-warn-label: var(--dsw-static-amber-600);
    --dsw-alias-state-warn-primary: var(--dsw-static-amber-500);
    --dsw-alias-state-warn-secondary: var(--dsw-static-amber-400);
    --dsw-alias-state-warn-tertiary: var(--dsw-static-amber-900);

    --dsw-alias-toast-bg: var(--dsw-static-neutral-bluish-750);
    --dsw-alias-tooltip-bg: var(--dsw-static-neutral-bluish-750);

    --dsw-specific-bubble: @surface0;
    --dsw-specific-input-major: @surface0;
    --dsw-specific-login-input: var(--dsw-static-neutral-900);
    --dsw-specific-menu: var(--dsw-alias-bg-layer-3);
    --dsw-specific-selector: fade(@text, 14%);
    --dsw-specific-sidebar-fill: @mantle;
    --dsw-specific-sidebar-nav-item-active-accent: @surface0;
    --dsw-specific-sidebar-nav-item-active: @surface0;
    --dsw-specific-sidebar-nav-item-hover: fade(@text, 8%);
    --dsw-specific-tip: var(--dsw-static-neutral-bluish-800);

    --dsr-bg: @crust;
    --dsr-text-0: @text;
    --dsr-text-1: @subtext1;
    --dsr-text-2: @subtext0;
    --dsr-text-3: @overlay2;
    --dsr-text-4: @overlay1;
    --dsr-border-1: rgb(var(--ds-rgb-neutral-450));
    --dsr-border-2: rgb(var(--ds-rgb-neutral-600));
    --dsr-input-border: #5a5a69;
    --dsr-input-bg: #404045;
    --dsr-button-main-bg: #509fff;
    --dsr-button-main-bg-hover: #4166d5;
    --dsr-button-second-bg: var(--dsr-main-2);
    --dsr-button-grey-0: rgb(var(--ds-rgb-neutral-600));
    --dsr-button-grey-1: rgb(var(--ds-rgb-neutral-650));
    --dsr-button-grey-2: rgb(var(--ds-rgb-neutral-700));
    --dsr-delete-button-bg: rgb(var(--ds-rgb-red-500) / 0.85);
    --dsr-delete-button-bg-hover: rgb(var(--ds-rgb-red-550) / 0.45);
    --dsr-tooltip-fg: rgb(var(--ds-rgb-zinc-650));
    --dsr-tooltip-bg: #000;
    --dsr-side-bg: #212327;
    --dsr-side-hover-bg-rgb: 51, 51, 51;
    --dsr-side-hover-bg: rgb(var(--ds-rgb-neutral-750));
    --dsr-icon-fg-1: rgb(var(--ds-rgb-neutral-350));
    --dsr-icon-hover-0: rgb(var(--ds-rgb-neutral-500));
    --dsr-icon-hover-1: rgb(var(--ds-rgb-neutral-700));
    --dsr-side-icon-hover: rgb(var(--ds-rgb-zinc-750));
    --dsr-error-fg: rgb(var(--ds-rgb-red-450));
    --dsr-risk-text: #e4773d;
    --dsr-risk-border: #4c4740;
    --dsr-risk-fill: #31302e;

    .ds-elevated, [data-elevated] {
      #ds-rgb() !important;
    }
    &, .ds-theme {
      #ds-rgb() !important;

      --wip-ds-color-bg-tooltip: @surface0;
    }

    .ds-sign-up-form__main {
      background: @base;
    }
    .ds-switch.ds-switch.ds-switch {
      --switch-color: @surface2;
      --switch-thumb-color: if(@flavor = latte, @base, @text);
      &.ds-switch--checked {
        --switch-color: @accent;
        --switch-thumb-color: @base;
      }
    }
    .ds-basic-button--primary {
      --ds-primary-button-text-color: @base;
    }
    .ds-checkbox svg {
      color: @base;
    }

    .ds-tooltip {
      --tooltip-text-color: @text;
    }

    /* Fade out text on active sidebar nav item */
    ._546d736.b64fb9ae ._254829d {
      --mask-base-color: #lib.rgbify(@surface0)[];
    }
    /* Fade out text on hovered sidebar nav item */
    ._546d736 ._254829d {
      --mask-base-color: #lib.rgbify(@surface0)[];
    }

    /* Fade out on top of conversation */
    .c99b79f8.c99b79f8.c99b79f8 {
      background: linear-gradient(to bottom, @crust, transparent);
    }
    /* Fade out on top of conversation when multiselect active */
    .a51c5344 .c99b79f8.c99b79f8.c99b79f8 {
      background: linear-gradient(
        to bottom,
        var(--dsw-alias-bg-multi-select),
        transparent
      );
    }

    /* Response feedback rating radio button focus */
    ._74d6322
      .ds-radio-button-group
      .ds-radio-button.ds-radio-button--active::after {
      box-shadow: var(--radio-button-group-button-outline-box-shadow-focus);
    }

    /* Send button icon */
    ._7436101 {
      color: @base;
    }
  }
}

